import altair as alt
import pandas as pd
import streamlit as st

import charts as C
import core
import mock_company as MC

st.title("Mock company walkthrough")
st.warning("**Harbor Supply Co. is fictional.** It is a made-up 6-person janitorial-supply "
           "distributor whose true settings are known, so every step below can be graded. "
           "Its order history is generated by the independent simulator, playing the role "
           "of a real company's system export.", icon=":material/info:")

with st.sidebar:
    st.subheader("Walkthrough settings")
    n_orders = st.select_slider("Orders in the history", [5_000, 10_000, 20_000, 40_000],
                                value=20_000, help="20,000 orders is about 5 weeks at 22 orders/hour.")
    seed = st.number_input("History seed", 1, 9999, 1, help="Change it to see a different "
                           "but statistically identical history.")


@st.cache_data(show_spinner="Generating the order history...")
def _history(n, s):
    return MC.history(n, s)


@st.cache_data(show_spinner=False)
def _estimates(n, s):
    return MC.estimates(_history(n, s))


orders = _history(n_orders, seed)

# ---------------------------------------------------------------- 1
st.header("1 · Pull the order history")
st.markdown(f"One row per order per station: when it arrived, when work started, when it "
            f"finished. **{len(orders):,} rows** covering {orders['order_id'].nunique():,} orders.")
st.dataframe(orders.head(9), width="stretch", hide_index=True)

# ---------------------------------------------------------------- 2
st.header("2 · Run the validation gate")
rep = MC.gate(orders)
(st.error if rep.fatal else st.success)(rep.summary().split("\n")[0])
for f in rep.findings:
    st.markdown(f"- {f}")
st.caption("The gate never fixes data silently. It reports, and rejects the data outright "
           "when problems are large enough to bias the estimates.")

# ---------------------------------------------------------------- 3
st.header("3 · Estimate the model's inputs from timestamps")
est = _estimates(n_orders, seed)
show = est[["Station", "Arrivals/hr (estimated)", "Speed/hr per worker (estimated)",
            "Variability cv (estimated)", "Orders seen"]]
st.dataframe(show.style.format(precision=3), width="stretch", hide_index=True)
st.markdown("Crew sizes don't appear in an order export, so they come from the owner:")
cols = st.columns(len(MC.TRUTH))
workers = {s.name: cols[i].number_input(f"Workers at {s.name}", 1, 20, s.workers, key=f"mw_{s.name}")
           for i, s in enumerate(MC.TRUTH)}
st.caption("At a real company, check this against effective capacity: in the real "
           "call-center test, headcount overstated capacity by about 2.6× (changelog C-007).")

# ---------------------------------------------------------------- 4
st.header("4 · Predict, and check the prediction against the history")
try:
    op = MC.operation_from(est, workers)
    mv = MC.model_vs_history(op, orders)
except core.ModelError as e:
    st.error(f"The model stopped instead of guessing: {e}")
    st.stop()
st.dataframe(mv.style.format({"Utilization (model)": "{:.0%}", "Wait error": "{:+.0%}"},
                             precision=2), width="stretch", hide_index=True)
long = pd.concat([
    mv[["Station", "Wait, model (min)"]].rename(columns={"Wait, model (min)": "minutes"}).assign(Series="Model"),
    mv[["Station", "Wait, history (min)"]].rename(columns={"Wait, history (min)": "minutes"}).assign(Series="Simulation"),
])
ch = alt.Chart(long).mark_bar(cornerRadiusTopLeft=4, cornerRadiusTopRight=4).encode(
    x=alt.X("Station:N", sort=list(mv["Station"]), title=None, axis=alt.Axis(labelAngle=0)),
    xOffset=alt.XOffset("Series:N", sort=["Model", "Simulation"]),
    y=alt.Y("minutes:Q", title="Average wait (minutes)"),
    color=alt.Color("Series:N", scale=alt.Scale(domain=["Model", "Simulation"], range=[C.MODEL, C.SIM]),
                    legend=alt.Legend(title=None, labelExpr="datum.label == 'Simulation' ? 'History (what happened)' : 'Model prediction'")),
    tooltip=["Station:N", "Series:N", alt.Tooltip("minutes:Q", format=".2f")])
st.altair_chart(C.finish(ch, 260), width="stretch")
st.caption("Downstream stations used to be predicted 24% and 43% too high, because the model "
           "assumed random arrivals everywhere. Passing variability down the line (C-009) "
           "fixed it; the correction then passed a pre-registered held-out check.")

# ---------------------------------------------------------------- 5
st.header("5 · Rank the possible changes")
names = [c.name for c in MC.CANDIDATES]
chosen = st.multiselect("Changes the owner is considering", names, default=names)
budget = st.number_input("Budget for one-time costs ($)", 0.0, 1_000_000.0, 100_000.0, 5_000.0)
cands = [c for c in MC.CANDIDATES if c.name in chosen]
st.dataframe(pd.DataFrame([{"Change": c.name, "Station": c.station,
                            "What it does": (f"{(c.amount - 1):+.0%} speed" if c.kind == "speed"
                                             else f"+{int(c.amount)} worker"),
                            "One-time $": c.install_cost, "Yearly $": c.annual_cost} for c in cands]),
             width="stretch", hide_index=True)
if not cands:
    st.stop()
best, ranked = MC.rank(op, cands, budget)
plans = pd.DataFrame([{"Plan": " + ".join(cv.names) or "Do nothing",
                       "Value $/yr": cv.value_per_year,
                       "Promised savings $/yr": cv.gross_savings_per_year,
                       "Annualized cost $/yr": cv.annualized_cost} for cv in ranked[:8]])
st.dataframe(plans.style.format({c: "${:,.0f}" for c in plans.columns if "$" in c}),
             width="stretch", hide_index=True)
rec_names = list(best.names)
st.success(f"**Recommendation:** {' + '.join(rec_names) or 'do nothing'}, worth "
           f"{core.money(best.value_per_year)}/yr after costs.")

# ---------------------------------------------------------------- 6
st.header("6 · Did the decision actually deliver?")
st.markdown("The model promised savings. Here we make the change to the **true** operation, "
            "re-run it many times, and measure the savings that actually showed up. Each "
            "replication runs before and after with the same random seed (common random "
            "numbers), so the difference comes from the change, not from luck.")
reps = st.slider("Replications", 4, 30, 10)
pick = st.selectbox("Plan to check", [p for p in plans["Plan"] if p != "Do nothing"] or ["Do nothing"])
if pick != "Do nothing" and st.button("Run the check", type="primary"):
    plan_c = [c for c in MC.CANDIDATES if c.name in pick.split(" + ")]
    promised = float(plans.loc[plans["Plan"] == pick, "Promised savings $/yr"].iloc[0])
    with st.spinner(f"Re-simulating the true operation {2 * reps} times..."):
        v = MC.verify_plan(plan_c, reps, n_orders)
    inside = v["lo"] <= promised <= v["hi"]
    a, b, c = st.columns(3)
    a.metric("Model promised", core.money(promised) + "/yr")
    b.metric("Actually delivered (mean)", core.money(v["mean"]) + "/yr",
             delta=f"{v['mean'] / promised - 1:+.1%} vs promise" if promised else None,
             delta_color="off")
    c.metric("95% confidence interval", f"{core.money(v['lo'])} to {core.money(v['hi'])}")
    (st.success if inside else st.warning)(
        "The promise falls inside the 95% interval of what actually happened."
        if inside else "The promise falls outside the 95% interval: the model mis-priced this plan.")
    reps_df = pd.DataFrame({"replication": range(1, len(v["values"]) + 1), "savings": v["values"]})
    dots = alt.Chart(reps_df).mark_circle(color=C.SIM, size=70).encode(
        x=alt.X("replication:O", title="Replication"),
        y=alt.Y("savings:Q", title="Realized savings ($/yr)", scale=alt.Scale(zero=False)),
        tooltip=["replication:O", alt.Tooltip("savings:Q", format="$,.0f")])
    rule = alt.Chart(pd.DataFrame({"p": [promised]})).mark_rule(color=C.MODEL, strokeWidth=2).encode(
        y="p:Q", tooltip=[alt.Tooltip("p:Q", format="$,.0f", title="model promised")])
    st.altair_chart(C.finish(dots + rule, 260), width="stretch")
    st.caption("Orange dots: savings measured in each replication. Blue line: the model's promise.")

# ---------------------------------------------------------------- key
with st.expander("Answer key: Harbor Supply's true settings"):
    st.dataframe(pd.DataFrame([{"Station": s.name, "Speed/hr per worker": s.service_rate,
                                "Workers": s.workers, "Variability cv": s.cv} for s in MC.TRUTH]),
                 hide_index=True)
    st.markdown(f"True arrival rate: **{MC.TRUTH_LAMBDA} orders/hour**. Costs: "
                f"margin ${MC.COSTS['margin']}/order, waiting ${MC.COSTS['waiting_cost']}/order-hour, "
                f"{MC.COSTS['hours_per_year']:,.0f} operating hours/year.")
